{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    n = len(segments)
    allocations = [seg["minimum"] for seg in segments]
    min_sum = sum(allocations)
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_priority = None
        for i, seg in enumerate(segments):
            if allocations[i] < seg["capacity"]:
                priority = seg["importance"] / (allocations[i] + 1)
                if best_idx == -1 or priority > best_priority or (priority == best_priority and i < best_idx):
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    total = sum(allocations)
    by_name = {seg["name"]: allocations[i] for i, seg in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": total}
